async function navigateFixture(page: Page, url: string): Promise<void> {
  const iframe = page.getByTestId("game-iframe");
  await iframe.evaluate((element) => {
    element.removeAttribute("data-fixture-navigation-loaded");
    element.addEventListener("load", () => element.setAttribute("data-fixture-navigation-loaded", "true"), { once: true });
  });
