  await page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("body").evaluate((_, destination) => {
    window.location.href = destination;
  }, url);
  await expect(iframe).toHaveAttribute("data-fixture-navigation-loaded", "true");
  await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
