test("should reconnect after cross-origin navigation and dispose while inaccessible", async ({ page }) => {
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  // A genuinely different origin, entirely fulfilled by the test runner.
  const externalUrl = "https://arcade-frame.invalid/input-fixture";
  await page.route(externalUrl, (route) => route.fulfill({ contentType: "text/html", body: inputFixture }));
  await openPlayer(page);
  await showControls(page);
  const iframe = page.getByTestId("game-iframe");
  const localUrl = await iframe.evaluate((element: HTMLIFrameElement) => element.src);
  const frame = page.frameLocator(`iframe[title="${gameTitle} game"]`);
  const controls = page.getByRole("region", { name: "Game controls", exact: true });
  const right = controls.getByRole("button", { name: "Move right", exact: true });
  const action = controls.getByRole("button", { name: "A (Z key)", exact: true });
  for (let cycle = 0; cycle < 2; cycle++) {
    await right.dispatchEvent("pointerdown", { pointerId: 81, pointerType: "mouse", button: 0, buttons: 1 });
    await expect.poll(() => recordedKeys(page)).toContainEqual({ type: "keydown", code: "ArrowRight", key: "ArrowRight" });
    await navigateFixture(page, externalUrl);
    await expect.poll(() => iframe.evaluate((element: HTMLIFrameElement) => element.contentDocument === null)).toBe(true);
    await right.dispatchEvent("pointercancel", { pointerId: 81, pointerType: "mouse" });
    await right.click();
    expect(await recordedKeys(page)).toEqual([]);
    await action.focus();
    await page.keyboard.down("Enter");
    await navigateFixture(page, localUrl);
    await expect(action).toBeFocused();
    await page.keyboard.up("Enter");
    expect(await recordedKeys(page)).toEqual([]);
    await expect(frame.locator("html")).toHaveAttribute("data-arcade-controls-visible", "true");
    // A working focus subscription must remember this input after host focus.
    await frame.locator("#ordinary-input").focus();
    await right.click();
    expect(await recordedKeys(page)).toEqual([]);
    await frame.locator("body").evaluate(() => (document.activeElement as HTMLElement)?.blur());
    await right.click();
    const expected = [
      { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
      { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
    ];
    await expect.poll(() => recordedKeys(page)).toEqual(expected);
    await expect(frame.locator("#focused-key-events")).toHaveText(JSON.stringify(expected));
    // Verify the returned document's blur listener, not just fresh key delivery.
    await right.dispatchEvent("pointerdown", { pointerId: 82, pointerType: "mouse", button: 0, buttons: 1 });
    await frame.locator("body").evaluate(() => window.dispatchEvent(new Event("blur")));
    await right.dispatchEvent("pointercancel", { pointerId: 82, pointerType: "mouse" });
    await expect.poll(() => recordedKeys(page)).toEqual([...expected, ...expected]);
  }
  // Close directly after navigation has committed but before host load cleanup.
  // This independently exercises unmounting the previously admitted subscription.
  await iframe.evaluate((element: HTMLIFrameElement) => {
    element.addEventListener("load", (event) => {
      element.setAttribute("data-fixture-navigation-loaded", "true");
      event.stopImmediatePropagation();
    }, { capture: true, once: true });
  });
  await navigateFixture(page, externalUrl);
  await page.getByRole("button", { name: "Back to games", exact: true }).click();
  await expect(page.getByTestId("game-player")).toBeHidden();
  await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
  await expect(frame.locator("#key-events")).toHaveText("[]");
  await showControls(page);
  await right.click();
  await expect.poll(() => recordedKeys(page)).toEqual([
    { type: "keydown", code: "ArrowRight", key: "ArrowRight" },
    { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
  ]);
  expect(errors).toEqual([]);
});

