    { type: "keyup", code: "ArrowRight", key: "ArrowRight" },
  ]);
});

for (const source of ["host", "iframe"] as const) {
  test(`should detect first ${source} touch after reopening and retain capability`, async ({ page }) => {
    await page.addInitScript(() => {
      const matchMedia = window.matchMedia.bind(window);
      window.matchMedia = (query) => {
        const result = matchMedia(query);
        if (query === "(pointer: coarse)") Object.defineProperty(result, "matches", { value: false });
        return result;
      };
    });
    await openPlayer(page);
    const controls = page.getByRole("region", { name: "Game controls", exact: true });
    await expect(controls).toBeHidden();
    await page.getByRole("button", { name: "Back to games", exact: true }).click();
    await expect(page.getByTestId("game-player")).toBeHidden();
    await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
    await expect(page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("#key-events")).toHaveText("[]");
    await expect(controls).toBeHidden();
    const target = source === "host"
      ? page.getByTestId("game-player")
      : page.frameLocator(`iframe[title="${gameTitle} game"]`).locator("body");
    await target.dispatchEvent("pointerdown", { pointerId: 84, pointerType: "touch", button: 0 });
    await expect(controls).toBeVisible();
    await page.getByRole("button", { name: "Hide controls", exact: true }).click();
    await expect(controls).toBeHidden();
    await page.getByRole("button", { name: "Back to games", exact: true }).click();
    await expect(page.getByTestId("game-player")).toBeHidden();
    await page.getByRole("button", { name: `Play ${gameTitle}`, exact: true }).click();
    await expect(controls).toBeVisible();
  });
}

